#include "../Source/HarmonicDSP.h"
#include <cmath>
#include <cstdlib>
#include <iostream>
#include <random>
#include <vector>
static void check(bool v,const char*n){if(!v){std::cerr<<"FAIL: "<<n<<'\n';std::exit(1);}}static double projection(const std::vector<float>&x,double f,double sr,size_t begin){double s=0,c=0;for(size_t n=begin;n<x.size();++n){double p=2*3.14159265358979323846*f*n/sr;s+=x[n]*std::sin(p);c+=x[n]*std::cos(p);}return 2*std::sqrt(s*s+c*c)/(x.size()-begin);}static std::vector<float>render(double f,int harmonic,float color=0){constexpr double sr=48000;cloudy::AnalysisBank bank;bank.prepare(sr);std::vector<float>out(192000);for(size_t n=0;n<out.size();++n){float x=float(.5*std::sin(2*3.14159265358979323846*f*n/sr));auto a=bank.process({x,x});float full=cloudy::complexHarmonic(a[0],a[1],harmonic),low=cloudy::complexHarmonic(a[2],a[3],harmonic),high=cloudy::complexHarmonic(a[4],a[5],harmonic);out[n]=cloudy::blendColor(full,low,high,color);}return out;}
int main(){constexpr double sr=48000;constexpr size_t settle=48000;auto h9=render(500,9);double wanted=projection(h9,4500,sr,settle),h8=projection(h9,4000,sr,settle),h10=projection(h9,5000,sr,settle),h11=projection(h9,5500,sr,settle);std::cout<<"H9="<<wanted<<" H8="<<h8<<" H10="<<h10<<" H11="<<h11<<'\n';check(wanted>.35,"strong H9");check(h8<wanted*.001&&h10<wanted*.001&&h11<wanted*.001,"adjacent harmonics below -60 dB");check(projection(render(500,2),1000,sr,settle)>.35,"debug H2");check(projection(render(300,11),3300,sr,settle)>.35,"debug H11");auto lowMinus=render(100,9,-1),lowPlus=render(100,9,1);check(projection(lowMinus,900,sr,settle)>projection(lowPlus,900,sr,settle),"negative color favors lows");auto highMinus=render(1800,9,-1),highPlus=render(1800,9,1);check(projection(highPlus,16200,sr,settle)>projection(highMinus,16200,sr,settle),"positive color favors highs");cloudy::AnalysisBank bank;bank.prepare(sr);std::mt19937 rng(9);std::uniform_real_distribution<float>d(-1,1);for(int n=0;n<20000;++n){auto a=bank.process({d(rng),d(rng)});for(int c=0;c<2;++c)check(std::isfinite(cloudy::complexHarmonic(a[size_t(c*6)],a[size_t(c*6+1)],9)),"finite output");}std::cout<<"PASS Cloudy9 analytic harmonic tests\n";}
